// TAG_MAP: tag_id → tag_name (tags_10_PLC-D.csv 기준)
var TAG_MAP = {
    1: "자동모드",
    2: "수동모드",
    3: "상부 매거진 서보 ON",
    4: "공급 서보 ON",
    5: "피딩 서보 ON",
    6: "공급 서보 ON",
    7: "리벳팅 서보 ON",
    8: "공급 서보 ON",
    9: "서보 활성화 ON"
};

var p = msg.payload;
var result = {
    plc_id: p.plc_id,
    timestamp: p.timestamp,
    count: p.count,
    tags: []
};

if (p.data && p.data.length > 0) {
    for (var i = 0; i < p.data.length; i++) {
        var d = p.data[i];
        var val = (d.v_bool !== undefined && d.v_bool !== null) ? d.v_bool :
                  (d.v_float !== undefined && d.v_float !== null) ? d.v_float :
                  (d.v_int !== undefined && d.v_int !== null) ? d.v_int :
                  (d.v_bigint !== undefined && d.v_bigint !== null) ? d.v_bigint :
                  (d.v_text !== undefined && d.v_text !== null) ? d.v_text : null;
        result.tags.push({
            tag_id: d.tag_id,
            tag_name: TAG_MAP[d.tag_id] || ("tag_" + d.tag_id),
            value: val,
            data_type: d.data_type || ""
        });
    }
}

msg.payload = result;
return msg;
